<?php
declare(strict_types=1);
return static function(PDO$pdo):void{
    $pdo->exec("ALTER TABLE program_manuals ADD COLUMN reconciliation_status ENUM('Not Started','Pending Approval','Approved','Rejected') NOT NULL DEFAULT 'Not Started' AFTER status,ADD COLUMN reconciliation_submitted_by INT NULL AFTER reconciliation_status,ADD COLUMN reconciliation_submitted_at DATETIME NULL AFTER reconciliation_submitted_by,ADD COLUMN reconciliation_approved_by INT NULL AFTER reconciliation_submitted_at,ADD COLUMN reconciliation_approved_at DATETIME NULL AFTER reconciliation_approved_by,ADD COLUMN reconciliation_note TEXT NULL AFTER reconciliation_approved_at,ADD CONSTRAINT fk_manual_submitter FOREIGN KEY(reconciliation_submitted_by) REFERENCES users(id) ON DELETE SET NULL,ADD CONSTRAINT fk_manual_approver FOREIGN KEY(reconciliation_approved_by) REFERENCES users(id) ON DELETE SET NULL");
    $pdo->exec("CREATE TABLE program_manual_plos(id INT AUTO_INCREMENT PRIMARY KEY,program_manual_id INT NOT NULL,plo_code VARCHAR(30) NOT NULL,domain VARCHAR(100) NULL,description TEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0,UNIQUE KEY uq_manual_plo(program_manual_id,plo_code),CONSTRAINT fk_manual_plo_manual FOREIGN KEY(program_manual_id) REFERENCES program_manuals(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE program_manual_courses(id INT AUTO_INCREMENT PRIMARY KEY,program_manual_id INT NOT NULL,semester_no INT NULL,course_code VARCHAR(50) NULL,course_name VARCHAR(255) NOT NULL,credit_hours DECIMAL(6,2) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,KEY idx_manual_course_code(program_manual_id,course_code),CONSTRAINT fk_manual_course_manual FOREIGN KEY(program_manual_id) REFERENCES program_manuals(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
};
